{
  "name": "loss_pairwise_advantage_tanh_softplus",
  "intuition": "Use a pairwise ranking loss that normalizes advantage gap and applies a smooth asymptotic penalty via tanh combined with softplus, promoting margin-like separation but smoothly saturating the loss, shifting from margin-based to smooth monotonic penalty paradigm.",
  "pseudocode": "adv_norm = tanh(clamp(advantage_gap / (abs(advantage_gap) + epsilon), -1, 1)); difference = log_prob_w - log_prob_l; margin = difference - adv_norm; loss = softplus(margin); weighted_loss = weight * loss; output = mean(weighted_loss)",
  "hyperparams": {
    "paradigm_family": "pairwise_smooth_ranking",
    "signal_family": "advantage_gap",
    "link_family": "tanh_softplus",
    "agg_family": "mean",
    "constraint_family": "clamp_and_normalize"
  },
  "operators_used": ["tanh", "clamp", "abs", "softplus", "mean", "mul", "sub", "add", "div"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    adv_gap = batch['advantage_gap']\n    eps = 1e-8\n    # Normalize advantage gap into [-1,1] using scaled tanh\n    adv_norm = ops.tanh(ops.clamp(adv_gap / (ops.abs(adv_gap) + eps), -1.0, 1.0))\n    margin = (lpw - lpl) - adv_norm\n    loss = ops.softplus(margin)\n    if weight is not None:\n        loss = loss * weight\n    return ops.mean(loss)"
}

{
  "name": "pairwise_advantage_cost_gap",
  "intuition": "This loss uses the advantage difference weighted by the cost gap, promoting preference for pairs with higher advantages and larger cost gaps. It encourages the model to favor options with better relative advantage and substantial cost differences, aligning the policy with the desired preference ranking.",
  "pseudocode": "loss = sum over pairs of (logsigmoid(advantage_w - advantage_l) * clamp(cost_gap, min=0, max=inf))",
  "hyperparams": {
    "paradigm_family": "pairwise",
    "signal_family": "advantage",
    "link_family": "sigmoid",
    "agg_family": "weighted_mean",
    "constraint_family": "monotonic"
  },
  "operators_used": ["logsigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    advantage_w = batch['advantage_w']\n    advantage_l = batch['advantage_l']\n    cost_gap = batch['cost_gap']\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    weight = batch['weight']\n    advantage_diff = advantage_w - advantage_l\n    weighted_advantage = logsigmoid(advantage_diff)\n    cost_mask = ops.clamp(cost_gap, min=0)\n    loss_terms = weighted_advantage * cost_mask\n    loss_mean = ops.reduce_mean(loss_terms)\n    return loss_mean"
}

{
  "name": "loss_pairwise_advantage_tanh_margin",
  "intuition": "Shift from a margin-based logsigmoid loss to a smooth, bounded margin loss using a tanh transformation of advantage-weighted log prob differences, encouraging nuanced margin sensitivity.",
  "pseudocode": "adv = advantage_gap\nmargin = clamp(lpw - lpl, -5, 5)\nscore = tanh(margin * adv)\nloss = mean(weight * (1 - score))",
  "hyperparams": {
    "paradigm_family": "pairwise_smooth_margin",
    "signal_family": "advantage_gap",
    "link_family": "tanh",
    "agg_family": "mean",
    "constraint_family": "clamp_bounded"
  },
  "operators_used": ["tanh", "clamp", "mean", "mul", "sub"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    adv = batch['advantage_gap']\n    margin = ops.clamp(lpw - lpl, -5.0, 5.0)\n    score = ops.tanh(margin * adv)\n    loss = 1.0 - score\n    if weight is not None:\n        loss = loss * weight\n    return loss.mean()"
}

{
  "name": "pairwise_advantage_cost_gap_loss",
  "intuition": "This loss computes the difference in advantage signals weighted by cost gap, emphasizing pairs where the advantage difference aligns with the cost difference, thereby promoting preference signals that favor lower-cost options with higher advantage. Using advantage and cost_gap signals helps guide the model towards better trade-offs, ensuring the preference aligns with the objective of preference optimization. The pairwise structure captures relative preferences rather than absolute scores, which is effective in RL4CO settings.",
  "pseudocode": "loss = -mean(logsigmoid(advantage_w - advantage_l + alpha * (cost_gap_w - cost_gap_l)))",
  "hyperparams": {
    "paradigm_family": "pairwise",
    "signal_family": "advantage",
    "link_family": "logistic",
    "agg_family": "mean",
    "constraint_family": "cost-based",
    "other_hparams": ""
  },
  "operators_used": ["logsigmoid", "sub", "mul", "add", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    alpha = float(extra.get(\"alpha\", 1.0))\n    log_prob_w = batch[\"log_prob_w\"]\n    log_prob_l = batch[\"log_prob_l\"]\n    advantage_w = batch[\"advantage_w\"]\n    advantage_l = batch[\"advantage_l\"]\n    cost_gap_w = batch[\"cost_gap\"]\n    cost_gap_l = batch[\"cost_gap\"]\n    score = advantage_w - advantage_l + alpha * (cost_gap_w - cost_gap_l)\n    loss_value = -ops.reduce_mean(ops.logsigmoid(score))\n    return loss_value"
}

{
  "name": "pairwise_advantage_loss",
  "intuition": "The loss leverages advantage signals to encourage the model to assign higher probability to better options over worse ones, directly optimizing the preference ordering. Using logsigmoid of advantage differences ensures a smooth, differentiable ranking signal that amplifies positive preferences and suppresses negative ones.",
  "pseudocode": "loss = -mean(logsigmoid(advantage_w - advantage_l) * weight)",
  "hyperparams": {
    "paradigm_family": "ranking",
    "signal_family": "advantage",
    "link_family": "logsigmoid",
    "agg_family": "mean",
    "constraint_family": "pairwise",
    "other_hparams": ""
  },
  "operators_used": ["logsigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    advantage_w = batch['advantage_w']\n    advantage_l = batch['advantage_l']\n    weight = batch['weight']\n    loss_tensor = -ops.mean(ops.logsigmoid(advantage_w - advantage_l) * weight)\n    return loss_tensor"
}

