  "intuition": "Implements a pairwise Bayesian preference loss using the normalized rank gap of advantage values as a weighting factor. Instead of raw advantage gaps, normalizes ranks using z-score to stabilize signals. Applies a logsigmoid link function on the log probability difference to encourage the winning log probability to be higher. Aggregates the weighted loss by mean, shifting paradigm to probabilistic ranking with normalized rank signals.",
  "pseudocode": "adv_rank = rank_gap(advantage_w, advantage_l)\nadv_rank_norm = zscore(adv_rank)\ndelta_lp = log_prob_w - log_prob_l\nloss_terms = -logsigmoid(delta_lp) * adv_rank_norm * weight\nloss = mean(loss_terms)",
  "hyperparams": {
    "paradigm_family": "pairwise_probabilistic_ranking",
    "signal_family": "advantage_gap_rank_normalized",
    "link_family": "logsigmoid",
    "agg_family": "mean",
    "constraint_family": "none"
  },
  "operators_used": ["rank_gap", "zscore", "logsigmoid", "mul", "sub", "mean", "neg"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    adv_w = batch['advantage_w']\n    adv_l = batch['advantage_l']\n    adv_rank = ops.rank_gap(adv_w, adv_l)\n    adv_rank_norm = ops.zscore(adv_rank)\n    delta_lp = ops.sub(lpw, lpl)\n    base_loss = ops.neg(ops.logsigmoid(delta_lp))\n    loss_terms = ops.mul(base_loss, adv_rank_norm)\n    if weight is not None:\n        loss_terms = ops.mul(loss_terms, weight)\n    return ops.mean(loss_terms)"
}

{
  "name": "pairwise_delta_rank_exp",
  "intuition": "This loss uses the delta rank signal to emphasize pairs with significant rank differences. By applying an exponential decay to the rank gap, it penalizes large decreases in rank more heavily, promoting preferred ordering while maintaining smoothness. It directly modulates the difference in log probabilities with this exponentially scaled rank gap, ensuring robust preference signals that focus on clear rank improvements.",
  "pseudocode": "delta = log_prob_w - log_prob_l\nrank_scale = exp(-clamp(delta_rank, 0, 20))\nloss = weight * (-delta * rank_scale)\nreturn sum(loss)",
  "hyperparams": {
    "paradigm_family": "pairwise_weighted_ranking_decay",
    "signal_family": "delta_rank",
    "link_family": "negexp_scale",
    "agg_family": "sum",
    "constraint_family": "clamp_bounded",
    "other_hparams": ""
  },
  "operators_used": ["exp", "clamp", "mul", "sub", "sum"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "delta_rank"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    delta_rank = batch['delta_rank']\n    delta = lpw - lpl\n    rank_scale = ops.exp(-ops.clamp(delta_rank, 0.0, 20.0))\n    loss = -delta * rank_scale\n    if weight is not None:\n        loss = loss * weight\n    return ops.sum(loss)"
}

