{
  "name": "loss_pairwise_rank_gap_negexp_weighted",
  "intuition": "The loss stabilizes numerical behavior by clamping delta_rank between 0 and 20 to avoid overly large exponentials, ensuring rank_scale remains in a manageable range. The weighted loss uses the negative delta log probabilities scaled by exponential decay of the clamped delta_rank. Weight is optional and safely applied only if present. This preserves monotonic weighting towards larger rank gaps without preference or expectation inconsistencies, explicitly requiring all keys the loss reads: log_prob_w, log_prob_l, delta_rank, and weight. The loss aggregates via sum, ensuring simplicity and numerical stability.",
  "implementation_hint": {
    "expects": [
      "log_prob_w",
      "log_prob_l",
      "weight",
      "delta_rank"
    ],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    delta_rank = batch['delta_rank']\n    delta = ops.sub(lpw, lpl)\n    clamped_delta_rank = ops.clamp(delta_rank, 0.0, 20.0)\n    rank_scale = ops.exp(ops.neg(clamped_delta_rank))\n    loss = ops.neg(ops.mul(delta, rank_scale))\n    if weight is not None:\n        loss = ops.mul(loss, weight)\n    return ops.sum(loss)"
}
